/**
 * Typed shape of the models.dev snapshot that lives in `catalog.ts`.
 *
 * The catalog is generated by `scripts/gen-catalog.mjs`; edit the generator
 * (not the snapshot) when models.dev changes shape.
 */

/** A model provider as published by models.dev. */
export interface Provider {
  readonly id: string;
  readonly name: string;
  /** Environment variables that can hold this provider's API key. */
  readonly env: readonly string[];
  /** Base URL of the provider's API. Absent for a few providers on models.dev. */
  readonly api?: string;
  /** Documentation URL. */
  readonly doc?: string;
  /** AI SDK package that speaks this provider's protocol. */
  readonly npm: string;
}

/** A single model entry as published by models.dev. */
export interface Model {
  readonly id: string;
  readonly name: string;
  readonly family?: string;
  /** Context window in tokens. */
  readonly context?: number;
  /** Maximum output tokens. */
  readonly output?: number;
  /** USD per 1M input tokens. */
  readonly inputCost?: number;
  /** USD per 1M output tokens. */
  readonly outputCost?: number;
  readonly reasoning?: boolean;
  readonly toolCall?: boolean;
  readonly attachment?: boolean;
  /** Knowledge cutoff, `YYYY-MM` or `YYYY-MM-DD`. */
  readonly knowledge?: string;
  /** Release date, `YYYY-MM-DD`. */
  readonly releaseDate?: string;
  /** Lifecycle marker such as `alpha`, `beta` or `deprecated`. */
  readonly status?: string;
}

/** A provider together with its models keyed by model id. */
export interface CatalogEntry extends Provider {
  readonly models: Readonly<Record<string, Model>>;
}

/** The whole generated snapshot. */
export interface Catalog {
  /** ISO-8601 timestamp of when the snapshot was generated. */
  readonly generatedAt: string;
  /** Upstream URL the snapshot was fetched from. */
  readonly source: string;
  /** Providers keyed by provider id. */
  readonly providers: Readonly<Record<string, CatalogEntry>>;
}
